insert into mach_channels (machine_key, org, lane, kind, country, city, role, brands, site, email, phone, stock, note, source, confidence, verdict) values
  ('R1700G', 'Borusan Makina Kazakhstan LLP (BMGS Kazakhstan, Borusan Cat Казахстан)', 'dealers', 'дилер', 'KZ', 'Алматы', 'официальный дилер Caterpillar в Казахстане с июля 1999 г.; полная линейка Cat, включая подземную горную технику', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.kz/', 'info-bmk@borusan.com', '8 800 0800 228', '14 точек в РК (Алматы, Астана, Караганда, Актау, Актобе, Шымкент, Сатпаев, Усть-Каменогорск, Костанай, Атырау, Уральск, Кокшетау); склад запчастей и цех ремонта; официальных поставок в РФ не делает', 'ближайший к РФ официальный канал по R1700G: на сайте дилера есть карточка машины https://www.borusancat.kz/en/equipment/new/13866077/Underground-Hard-Rock/18233686/R1700G . По подземному проекту Anglo Asian (Азербайджан) крупные узлы Cat держат на региональных складах Борусан в Турции и Казахстане — значит по R1700 позиции в регионе реально есть. Контакты и 14 адресов вытянуты из JSON карты локаций на собственном сайте Borusan Cat.', 'https://www.borusancat.com/en/contact/map', 'high', null),
  ('R1700G', 'Borusan Cat Kyrgyzstan (BMGS Kyrgyzstan)', 'dealers', 'дилер', 'KG', 'Бишкек', 'официальный дилер Caterpillar в Кыргызстане с 2003 г.; горная и дорожная техника, оригинальные запчасти и масла', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.kg/', 'info-bmkg@borusan.com', '+996 228 858 858', '3 точки: Бишкек, Балыкчы, Ош; глубокий склад — у головного дилера в Алматы/Турции', 'в каталоге есть R1700 (https://www.borusancat.kg/en/equipment/new/13866077/underground-hard-rock/730743084457382/r1700). Полезен как альтернативный ЕАЭС-адрес: КР в ЕАЭС, значит ввоз из КР в РФ без таможенной границы.', 'https://www.borusancat.com/en/contact/map', 'high', null),
  ('R1700G', 'Borusan Makina ve Güç Sistemleri Azerbaijan (BMGS Azerbaijan)', 'dealers', 'дилер', 'AZ', 'Баку', 'официальный дилер Caterpillar в Азербайджане с 1997 г.; первый в стране парк подземной техники Cat', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.az/', 'infoaz@borusancat.com', '+994 12 377 02 28', 'склад запчастей и расходников в Азербайджане (Баку-Шихово, Salyan Highway 15 km); крупные узлы — на региональных складах в Турции и Казахстане', 'в декабре 2023 г. Anglo Asian Mining получила на Гедабек 3 подземных погрузчика Cat R1700 (15 т) и 2 Cat 980UMA — первая подземная техника Cat в Азербайджане; сервис и запчасти по контракту ведёт Борусан. Это единственный известный парк R1700 у ближайших соседей РФ с формализованной запчастной поддержкой.', 'https://im-mining.com/2023/12/12/caterpillar-borusan-make-historic-underground-equipment-delivery-to-anglo-asian-mining-in-azerbaijan/', 'high', null),
  ('R1700G', 'Borusan Makina ve Güç Sistemleri Georgia (BMGS Georgia)', 'dealers', 'дилер', 'GE', 'Тбилиси (филиал Терджола)', 'официальный дилер Caterpillar в Грузии с 1997 г.', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.ge/', 'info-ge@borusancat.com', '+995 32 2 222 522', '2 точки: головной офис Тбилиси (Kakheti Highway 118) и филиал Терджола', 'Грузия — один из трёх-четырёх транзитных маршрутов оригинала в РФ; сам дилер в РФ не поставляет, но служит источником для реэкспортёров.', 'https://www.borusancat.com/en/contact/map', 'high', null),
  ('R1700G', 'Borusan Makina ve Güç Sistemleri A.Ş. (Borusan Cat Türkiye)', 'dealers', 'дилер', 'TR', 'Истанбул', 'официальный дилер Caterpillar в Турции с 1994 г.; головная компания группы дилеров Борусан (TR, AZ, GE, KZ, KG)', 'Caterpillar, SEM, FG Wilson, Faresin', 'https://www.borusancat.com/', 'info-cat@borusan.com', '+90 216 507 17 15', '40 точек в Турции (клиентские центры и ревизионные центры: Адана, Анкара, Анталья, Бурса, Диярбакыр, Испарта, Измир, Трабзон и др.); региональный склад крупных узлов Cat для Кавказа и Центральной Азии', 'принимает заказы запчастей через Parts.Cat.Com (собственная страница «Yedek Parça → Parça Mağazası (Parts.Cat.Com)»). Держит подземную линейку в каталоге (R1700). Турция — главный хаб пересборки цепочки на РФ после 2022 г.', 'https://www.borusancat.com/tr/part', 'high', null),
  ('R1700G', 'ИП ООО «Zeppelin Central Asia Machinery»', 'dealers', 'дилер', 'UZ', 'Ташкент', 'официальный дилер Caterpillar в Узбекистане (около 20 лет), часть Zeppelin GmbH — крупнейшего дилера Cat в Европе', 'Caterpillar, SEM', 'https://www.zeppelin.uz/', 'zub-centralasia@zeppelin.com', '+998 78 150 99 33', '4 точки: Ташкент (Сергели, Кольцевая, Ханабад), Наманган, Карши, Зарафшан; сервис 24/7', 'точка в Зарафшане — это промзона НГМК (Навоийский ГМК), то есть дилер уже работает по подземной и карьерной добыче. Раздел «Горная и карьерная техника» и «Сервис и запчасти» на сайте. Узбекистан не в ЕАЭС — ввоз в РФ через таможню.', 'https://www.zeppelin.uz/contacts', 'high', null),
  ('R1700G', 'Zeppelin Tajikistan', 'dealers', 'дилер', 'TJ', 'Душанбе', 'официальный дилер техники и энергетического оборудования Cat в Таджикистане', 'Caterpillar', 'https://www.zeppelin.tj/', 'info@zeppelin.tj', '+992 44 625 11 22', 'Душанбе, пр. Негмата Карабаева 200; глубина склада не заявлена', 'в каталоге есть раздел «Горная и карьерная техника» и «Сервис и запчасти»; поставлено более 300 машин Cat. Слабое звено по объёму, но формально официальный канал.', 'https://www.zeppelin.tj/brands/cat/', 'high', null),
  ('R1700G', 'ООО «Zeppelin Armenia»', 'dealers', 'дилер', 'AM', 'Абовян (Ереван)', 'официальный дилер Cat в Республике Армения (около 20 лет), часть Zeppelin GmbH', 'Caterpillar', 'https://www.zeppelin.am/', null, '+374 60 52 00 00', '4 подразделения, 3 сервисных центра (в т.ч. Каджаран и Техут — действующие рудники), 157 сотрудников', 'на собственном сайте прямо заявлен статус официального дилера Cat в Армении. Есть российский номер +7 800 100 14 51 на сайте — признак работы с российскими клиентами. Армения в ЕАЭС: ввоз в РФ без таможенной границы. Корпоративная почта на сайте не опубликована, только форма.', 'https://www.zeppelin.am/eng/', 'high', null),
  ('R1700G', 'Barloworld Mongolia LLC (ранее Wagner Asia Equipment LLC)', 'dealers', 'дилер', 'MN', 'Улан-Батор', 'официальный дилер Caterpillar в Монголии (дилерство с 1996 г., в 2021 г. выкуплено Barloworld)', 'Caterpillar, SEM, Michelin', 'https://www.barloworld.mn/', null, '7018 7588', 'сеть сервисных баз по Монголии; сильная горная компетенция (Оюу-Толгой, Таван-Толгой)', 'статус дилера подтверждён на собственном сайте Caterpillar (catused.cat.com — карточка дилера BARLOWORLD MONGOLIA LLC). Тот же владелец, что у российской «Восточной Техники», — практический мостик по оригиналу через Монголию. Корпоративной почты на сайте нет, только форма.', 'https://catused.cat.com/en/dealer.aspx?orgid=%7B42e2f3fa-97f8-46f0-916c-673c0c9b2063%7D', 'high', null),
  ('R1700G', 'Mohamed Abdulrahman Al-Bahar LLC', 'dealers', 'дилер', 'AE', 'Шарджа (головной офис)', 'официальный дилер Caterpillar по ОАЭ, Кувейту, Катару, Оману и Бахрейну; горное направление в наличии', 'Caterpillar, Cat Power Systems', 'https://www.albahar.com/', 'webinfo@albahar.com', '+971 6 543 3555', 'Шарджа (159 Al-Wasit Street, Ind. Area 3), Абу-Даби (Mussafah, Plot 36 Sector M-15), Дубай (склад запчастей, +971 4 266 0255), Джебель-Али; дежурная служба запчастей вне рабочих часов', 'крупнейший официальный источник оригинала в ОАЭ. Сам в РФ не поставляет, но именно вокруг него живёт дубайский слой реэкспортёров, через который оригинал доходит до РФ.', 'https://www.albahar.com/contact-us/locate-us/uae/', 'high', null),
  ('R1700G', 'Lei Shing Hong Machinery Ltd (LSHM)', 'dealers', 'дилер', 'CN', 'Куньшань (Цзянсу), группа — Гонконг', 'первый дилер Caterpillar в материковом Китае (с 1994 г.); территория — Шанхай, Цзянсу, Чжэцзян, Шаньдун, Хэнань, Аньхой, Хубэй', 'Caterpillar, Perkins', 'https://www.lsh.com/machinery/', 'info@lsh.com', '+86 512 5766 3168', 'сеть филиалов по востоку Китая, собственный Equipment Rebuild Center (капремонт узлов) и склад запчастей', 'Китай — фактический главный источник оригинала для РФ (по нашей таможне 2023 г. ровно 20 из 35 строк Cat шли от CATERPILLAR (QINGZHOU) CO. LTD, КНР). LSHM — легальный вход в китайскую дилерскую систему Cat. Контакты с корпоративного сайта группы LSH.', 'https://www.lsh.com/machinery/', 'high', null),
  ('R1700G', 'Lei Shing Hong Machinery North China (ранее WesTrac China)', 'dealers', 'дилер', 'CN', 'Пекин', 'региональный дилер Caterpillar по северу и северо-востоку Китая: Хэйлунцзян, Цзилинь, Ляонин, Шаньси, Хэбэй, Внутренняя Монголия, Пекин, Тяньцзинь', 'Caterpillar', 'https://www.lsh.com/machinery/', 'info@lsh.com', '+86 10 5902 1666', 'сеть по северным провинциям; горная специализация (наследие WesTrac China от Seven Group)', 'в 2017 г. Seven Group Holdings продала китайское горное дилерство (WesTrac China) группе Lei Shing Hong за 428 млн долл.; территория граничит с РФ и Монголией — практически удобная точка входа. Телефон пекинского офиса — из контактов корпоративного сайта LSH.', 'https://www.miningglobal.com/automation-and-ai/seven-group-holdings-sells-chinese-mining-machinery-arm-lei-shing-hong-dollar428mn', 'med', null),
  ('R1700G', 'China Engineers Limited (CEL), группа Sime Darby', 'dealers', 'дилер', 'CN', 'Фошань (Гуандун)', 'единственный дистрибьютор Cat в семи провинциях КНР: Гуандун, Гуанси, Хайнань, Фуцзянь, Цзянси, Хунань и Синьцзян', 'Caterpillar', 'http://cel-cat.com.cn', 'cel@simedarby.com.hk', '+86 757 2239 8880', '57 200 наименований на складе, не менее 85 % позиций — со склада; система складского учёта подключена к глобальной сети поставок запчастей Caterpillar', 'важнейшая деталь: в территорию CEL входит Синьцзян — то есть официальный дилерский склад Cat стоит вплотную к Казахстану, на сухопутном коридоре в ЕАЭС. Для закупки под R1700G это самый короткий официальный путь «оригинал → ЕАЭС → РФ».', 'https://www.simeindustrial.com/caterpillar-dealership/china-engineers-limited', 'high', null),
  ('R1700G', 'Gmmco Limited (CK Birla Group)', 'dealers', 'дилер', 'IN', 'Ченнаи', 'крупнейший дилер Caterpillar в Индии (с 1967 г.); юг, центр и запад Индии; горное направление выделено отдельно', 'Caterpillar, Cat Power Systems', 'https://www.gmmco.in/', 'sales@gmmcoindia.com', '1800 425 2546', 'более 100 филиалов, цеха капремонта (Бутибори/Нагпур, Ченнаи); онлайн-заказ Cat-запчастей, SIS 2.0, Cat Central, Cat Integrated Procurement', 'Индия — недооценённый канал: у Gmmco полноценный доступ к parts.cat.com и SIS 2.0, крупный склад и ремонтная база. Расчёты в рупиях, логистика в РФ — море/Иран или авиа.', 'https://www.gmmco.in/contact-us', 'high', null),
  ('R1700G', 'Gainwell Commosales Pvt Ltd (ранее Tractors India Pvt Ltd, TIPL)', 'dealers', 'дилер', 'IN', 'Колката', 'авторизованный дилер Cat по северу и востоку Индии и Бутану; сестринская Gainwell Engineering по лицензии Caterpillar делает подземную технику room-and-pillar и поставляет к ней запчасти', 'Caterpillar', 'https://www.gainwellindia.com/', null, null, 'более 80 филиалов, площадок и цехов; завод подземной техники на 35 акрах в Панагархе (Западная Бенгалия)', 'единственный в регионе дилер Cat с собственным производством подземной горной техники и обязательством поставлять aftermarket-запчасти к лицензированной подземной технике Cat. По ПДМ R1700G прямого мандата нет (лицензия — на room-and-pillar), но компетенция по подземке есть. Контактов на уровне корпоративной почты в открытом виде не нашёл.', 'https://northamericanmining.com/index.php/2022/04/19/gainwell-engineering-caterpillar-sign-underground-tech-deal/', 'med', null),
  ('R1700G', 'Eltrak S.A. (ELTRAK Group)', 'dealers', 'дилер', 'GR', 'Афины (Неа-Кифисия)', 'официальный дилер Caterpillar в Греции (с 1982 г.) и Болгарии; по линии судовых двигателей MaK территория Cat включает KZ, KG, TJ, TM, UZ, AM, AZ, GE, MD, MN, UA', 'Caterpillar, MaK', 'https://eltrak.gr/en/', null, '+30 210 8196800', 'склады в Греции и Болгарии', 'ВАЖНАЯ ОГОВОРКА: широкая центральноазиатская территория Eltrak в официальном локаторе Cat относится к судовым двигателям MaK, а не к землеройной и горной технике Cat — по машинам в этих странах дилеры Borusan и Zeppelin. Для R1700G Eltrak не канал; строку держим, чтобы никто не перепутал территории.', 'https://www.cat.com/en_US/by-industry/marine/mak-dealer-locator.html', 'med', null),
  ('R1700G', 'ООО «Восточная Техника» (ВТ), группа Barloworld', 'dealers', 'торговец', 'RU', 'Новосибирск', 'официальный дилер Caterpillar в РФ с 1998 г. по Сибири, Якутии и северу Дальнего Востока; сегодня на собственном сайте называет себя только «поставщик техники Cat, SEM»', 'Caterpillar, SEM, Weichai, DATC', 'https://www.vost-tech.ru/', 'info@vost-tech.ru', '8 800 250 70 60', '17 подразделений от Западной Сибири до Дальнего Востока, 17 складов запчастей, 7 сервисных центров; восстановленные и б/у запчасти отдельным разделом', 'ключевой факт для нас: ВТ реально ввозит оригинал — в нашей таможенной выборке 2023 г. ООО «Восточная Техника» стоит импортёром запчастей Cat из Германии и США. По открытым данным выручка 2023 г. > 20 млрд руб., за I кв. 2024 г. ввезено оборудования и запчастей Cat более чем на 24 млн долл. В марте 2025 г. закрыла малые подразделения (Алдан, Мирный, Москва, Нерюнгри, Петропавловск-Камчатский, Удачный, Улан-Удэ, Якутск). Barloworld подавал добровольное раскрытие в BIS (сентябрь 2024), итоговый отчёт — 1 сентября 2025 г., нарушений санкций США расследование не нашло. Слово «официальный дилер» с главной страницы сайта убрано — это надо учитывать в переписке.', 'https://www.vost-tech.ru/', 'high', null),
  ('R1700G', 'ООО «Мантрак Восток» (Mantrac Group, Mansour)', 'dealers', 'торговец', 'RU', 'Бор, Нижегородская обл.', 'был официальным дилером Caterpillar в РФ с 2000 г. по европейской части (Воркута, Гай, Екатеринбург, Казань, Москва, Пермь, Сургут, Тюмень, Уфа, Ухта, Челябинск)', 'Caterpillar, Bucyrus, SEM', null, null, null, 'нет: канал не работает', 'проверено вручную 12.09.2026: домен mantracvostok.ru отдаёт не сайт компании, а страницу-редирект на партнёрскую ссылку aviasales (`window.location = http://www.aviasales.ru/?marker=...mantracvostok_ru`), то есть домен отпущен/перепродан. HTTPS на нём не поднят. Mantrac Group публично сообщала о существенном сворачивании российской дочерней структуры. В РФ как канал по R1700G не рассматривать.', 'http://mantracvostok.ru/', 'high', null),
  ('R1700G', 'ООО «Цеппелин Русланд» (Zeppelin Russland)', 'dealers', 'торговец', 'RU', 'Москва', 'был официальным дилером Caterpillar по Центральному, Северо-Западному, части Приволжского и Южного ФО; сегодня — «официальный дилер сельхозтехники мировых производителей»', 'Agrifac, Agromaster, Nardi, KIVI-PEKKA, SEPPI, Western (Caterpillar в ассортименте нет)', 'https://www.zeppelin.ru/', 'zrs-help@zeppelin.ru', '+7 495 130 35 35', '7 филиалов в РФ, 9 брендов — все сельхоз; запчастей Cat не продаёт', 'проверено вручную: на главной странице zeppelin.ru слово Caterpillar не встречается ни разу, а карточка https://www.zeppelin.ru/products/arkhiv/brand-cat/r1700g/ помечена «АРХИВНАЯ МОДЕЛЬ… В настоящее время эта модель не доступна для продажи». Это самый чистый документальный след того, что немецкий канал Cat в РФ закрыт и заменён сельхозбизнесом. Потеря российского рынка стоила Zeppelin GmbH 16 % выручки в 2022 г.', 'https://www.zeppelin.ru/products/arkhiv/brand-cat/r1700g/', 'high', null),
  ('R1700G', 'ООО «Амур Машинери» / «Сахалин Машинери»', 'dealers', 'дилер', 'RU', 'Хабаровск', 'официальный дилер Caterpillar по Дальнему Востоку (более 25 лет); представительства Благовещенск, Тында, Находка, Южно-Сахалинск, Комсомольск', 'Caterpillar', 'https://amurmachinery.ru/', null, null, '8 складов запчастей, более 10 000 наименований; сервисные центры в Хабаровске и Благовещенске с высшей оценкой Cat «5 звёзд»', 'в справочнике дилеров Cat по РФ (обновление 01.12.2023) присутствует наравне с ВТ, Мантрак Восток и Цеппелин Русланд. В нашей таможенной выборке по ПДМ есть импортёр АО «Техсервис-Благовещенск» — тот же регион, тот же коридор через Хэйхэ. Собственный сайт из нашей среды не открывается (DNS/TLS), поэтому текущий статус на 2026 г. по первичному источнику не подтверждён — проверять до сделки.', 'https://exkavator.ru/dealers/producer/caterpillar', 'med', null),
  ('R1700G', 'Caterpillar Inc.', 'dealers', 'производитель-неоригинал', 'US', 'Ирвинг / Пеория', 'изготовитель; официального канала в РФ нет', 'Caterpillar, SEM, Cat Reman', 'https://www.caterpillar.com/', null, null, 'в РФ — нет', 'ОГОВОРКА ПО ПОЛЮ kind: в разрешённом перечне значений нет «производитель-оригинала», поставлено ближайшее — Caterpillar Inc. это изготовитель оригинала, а не неоригинала. хронология выхода: март 2022 — приостановка работы российских заводов («supply chain disruptions and sanctions»); апрель 2023 — остановка стройки в Санкт-Петербурге; ноябрь 2023 — Путин разрешил продажу ООО «ПСК-Новые решения»; 14 июня 2024 — активы переданы (завод в Тосно + лизинговая компания в Москве); июль 2024 — «Катерпиллар Тосно» переименован в ООО «Тосно», «Катерпиллар Файнэншл» — в ООО «Файнэншл»; апрель 2025 — выход формально зафиксирован; к декабрю 2025 г. проданы последние российские юрлица (~2,6 млрд руб.). Значит: гарантии завода, заводского сервиса и официальной поставки на РФ по R1700G не существует.', 'https://leave-russia.org/caterpillar', 'high', null),
  ('R1700G', 'ООО «ПСК-Новые решения» / Balchug Capital (Давид Амарян)', 'dealers', 'торговец', 'RU', 'Москва', 'покупатель российских активов Caterpillar: завод спецтехники в Тосно (Ленобласть) и лизинговая компания', '—', null, null, null, 'завод в Тосно; запчастями Cat не торгует', 'ПСК-Новые решения зарегистрировано в августе 2022 г., на 99 % принадлежит армянскому инвестфонду Balchug Capital. Сделка одобрена указом в ноябре 2023 г., закрыта 14.06.2024. Далее учредители менялись (июль 2024 — ООО «Инвестиционные решения», апрель 2025 — Мигаль А.П. и АО «Горизонт»). Для закупки запчастей R1700G бесполезно, но объясняет, почему у «наследника» нет ни каталога, ни доступа к SIS.', 'https://leave-russia.org/caterpillar', 'med', null),
  ('R1700G', 'Cat® Parts Store (parts.cat.com)', 'dealers', 'маркетплейс', 'US', '—', 'официальный интернет-магазин запчастей Caterpillar, ~1,5 млн позиций; заказ всегда идёт через выбранного дилера территории', 'Caterpillar, Cat Reman, Cat Classic', 'https://parts.cat.com/', null, null, 'склад — у дилера; забор со склада дилера или доставка дилером', 'механика важна для торгов: аккаунт в PCC привязывается к дилеру, поэтому покупка возможна только там, где у Cat есть дилер. Дилеры Борусан прямо описывают это на своих страницах («Parça Mağazası (Parts.Cat.Com) … заказ онлайн 24/7 без визита в точку продаж»). Для РФ дилера в системе нет, значит легальный PCC-заказ на российского получателя не собирается — только через юрлицо в KZ/KG/AM/TR/AE/CN. Из нашей среды сам parts.cat.com отдаёт 403 (гео/бот-фильтр), что косвенно подтверждает ограничение доступа.', 'https://www.borusancat.com/tr/part', 'med', null),
  ('R1700G', 'Cat® SIS 2.0 / SIS2GO (sis2.cat.com)', 'dealers', 'маркетплейс', 'US', '—', 'официальная система сервисной информации Cat: разузлование по модели и серийному номеру, схемы, процедуры, парт-номера', 'Caterpillar', 'https://sis2.cat.com/', null, null, '—', 'базовый доступ даёт аккаунт parts.cat.com (наборы, запчасти, безопасность), полный репозиторий — по платной годовой подписке Cat SIS Advanced, которую оформляет дилер. Интерфейс есть на русском. Практический вывод: без дилерского аккаунта разузловка R1700G по SIS для нас недоступна, и парт-номера приходится собирать по дилерским и вторичным каталогам.', 'https://www.petersoncat.com/parts/cat-service-information-system', 'med', null),
  ('R1700G', 'АО «ВЭД Агент»', 'dealers', 'торговец', 'RU', 'Новосибирск', 'таможенный брокер и импортёр полного цикла (Китай, Европа), консолидация грузов; офис в Шанхае', 'мультибренд', 'https://ved-agent.fis.ru/', null, '+7 383 328 43 84', 'сборные грузы из Китая и Европы; таможенное оформление, страхование', 'подтверждённый импортёр Caterpillar: в нашей таможенной выборке 2023 г. АО «ВЭД Агент» ввозило от CATERPILLAR INC (США) адаптер коронки ковша и фиксатор коронки — то есть GET-позиции, ровно тот класс деталей, что нужен по ковшу R1700G. Управляющий публично объясняет механику параллельного импорта.', 'https://ved-agent.fis.ru/', 'med', null),
  ('R1700G', 'ООО «СПК-Импорт» (spkamur.ru)', 'dealers', 'торговец', 'RU', 'Благовещенск', 'импорт и продажа запчастей для спецтехники из Китая, более 20 000 артикулов; Caterpillar в списке брендов', 'Caterpillar, SEM, XCMG, Komatsu, JCB, Shantui, Shehwa, FAW и 20+', 'https://spkamur.ru/', 'order@spkamur.ru', '8 800 707 65 94', 'склады Хэйхэ (КНР), Казань, Благовещенск; доставка по РФ 13 транспортными компаниями; гарантия до 6 месяцев по договору; работа с юрлицами — счёт, договор, НДС', 'подтверждённый импортёр Cat: в нашей таможне 4 строки Caterpillar и 4 строки по ПДМ на ООО «СПК-Импорт». Заявляет «оригинал и аналог по каждой позиции» — значит на запрос по R1700G надо жёстко требовать указания, что именно предлагается.', 'https://spkamur.ru/', 'high', null),
  ('R1700G', 'ООО «Хорошая Техника» (catparts.tech)', 'dealers', 'торговец', 'RU', 'Москва', 'поставка оригинальных запчастей Caterpillar для тех, у кого нет доступа к фирменному каналу', 'Caterpillar', 'https://catparts.tech/', 'lead@goodmash.ru', '+7 495 419 97 43', 'под заказ, международный прямой поставщик; наличие подтверждают по запросу', 'сама себя позиционирует как ответ на подделки и «аналоги сомнительного качества» — то есть работает в нише именно оригинала. Ни склада, ни сроков на сайте не заявлено: это посредник, цену и срок надо выбивать запросом.', 'https://catparts.tech/', 'med', null),
  ('R1700G', 'caterpillar-russia.com (поставки оборудования и запчастей Caterpillar)', 'dealers', 'торговец', 'RU', 'Москва', 'посредник по поставкам оборудования и оригинальных запчастей Caterpillar по РФ и СНГ', 'Caterpillar', 'https://caterpillar-russia.com/', 'sales@caterpillar-russia.com', '+7 495 125 10 49', 'заявлено: КП за 5 дней, доставка до 2 дней, гарантия 365 дней, фотоотчёт перед отгрузкой', 'осторожно: домен содержит товарный знак Caterpillar, юрлицо на сайте не раскрыто, статус к Caterpillar Inc. отношения не имеет. Заявленные «от 5 дней» по оригиналу для подземной техники выглядят нереалистично и требуют проверки конкретным парт-номером. Годится как один из адресов для контрольного запроса цены, не как основной канал.', 'https://caterpillar-russia.com/', 'low', null),
  ('R1700G', 'ProfiMiner (каталог поставщиков горной техники и запчастей)', 'dealers', 'маркетплейс', 'RU', 'Москва', 'отраслевой каталог: 44 компании в рубрике «поставщики запасных частей» для горной и карьерной техники, с локациями РФ, Беларуси, Китая и Венгрии', 'мультибренд', 'https://profiminer.ru/', 'info@profiminer.ru', '+7 901 184 85 33', '—', 'полезен как рабочий список адресов для рассылки ТКП по узлам R1700G и как независимая проверка статуса: карточка «Восточной Техники» там до сих пор описана как «официальный дилер компании Caterpillar в России с 1998 года, входит в группу Barloworld».', 'https://profiminer.ru/company/ccategory-part-dealer/', 'med', null),
  ('R1700G', 'ТОО «Hartex»', 'dealers', 'торговец', 'KZ', 'Алматы (и Усть-Каменогорск)', 'поставщик запчастей для спецтехники и дизельных двигателей, отдельный каталог Caterpillar (оригинал и аналоги)', 'Caterpillar и др.', 'https://hartex.kz/catalog/caterpillar/', 'sales@hartex.kz', '+7 771 116 44 44', 'более 30 000 запчастей; заявлена доставка по Казахстану, Киргизии и в Россию', 'прямо декларирует доставку в РФ — то есть готовая ЕАЭС-схема без таможенной границы на въезде. Адреса: Алматы, 8-й микрорайон 84а; Усть-Каменогорск, ул. Кожедуба 34/17 (Усть-Каменогорск — рядом с горными предприятиями ВКО).', 'https://hartex.kz/catalog/caterpillar/', 'high', null),
  ('R1700G', 'ТОО «Диггер-Про КЗ» (zemlekop.kz)', 'dealers', 'торговец', 'KZ', 'Астана', 'поставщик запчастей для спецтехники, каталог CAT; официальный представитель CARRARO и DANA SPICER в РК', 'Caterpillar, Carraro, Dana, ZF, Komatsu, Volvo, Perkins', 'https://zemlekop.kz/cat/', 'info@zemlekop.kz', '+7 7172 67 71 61', 'складской запас по востребованным фильтрам, уплотнениям и гидравлике; подбор по VIN машины или заводскому номеру детали; счёт, накладная, сертификат соответствия на каждую поставку', 'сильная сторона — трансмиссионная тема (Carraro/Dana): у R1700G шарнирно-сочленённая схема с мостами и гидромеханической передачей, так что это осмысленный адрес по мостам, дифференциалам и планетарным редукторам.', 'https://zemlekop.kz/cat/', 'high', null),
  ('R1700G', 'Q-Parts (quality-parts.kz / q-parts.kz)', 'dealers', 'торговец', 'KZ', 'Алматы', 'магазин запчастей для спецтехники Caterpillar (оригинал и качественные дубликаты)', 'Caterpillar, мультибренд', 'https://quality-parts.kz/g7223758-cat-caterpillar', 'info@q-parts.kz', '+7 727 317 11 11', 'склады Алматы и Астана; доставка по Казахстану, а также в Ташкент и Бишкек', 'по смыслу — розничный/мелкооптовый уровень. Годится для расходников и фильтров по R1700G, не для крупных узлов. По оригинальности требовать подтверждение: сами пишут про «качественные дубликаты».', 'https://quality-parts.kz/g7223758-cat-caterpillar', 'med', null),
  ('R1700G', 'ТОО «Rapid Parts Distribution» (RPD)', 'dealers', 'ремонт', 'KZ', 'Алматы', 'продажа оригинальных запчастей, сервис и ремонт газовых и дизельных силовых установок Caterpillar; официальный дилер DEIF в РК', 'Caterpillar, DEIF', 'https://rpd.kz/', 'info@rpd.kz', '+7 727 354 42 99', 'запчасти в наличии и под заказ по всем моделям (по заявлению на сайте)', 'узкая, но релевантная компетенция: R1700G построен на Cat C11/C15 ACERT, а RPD живёт ровно на двигателях Cat — капремонт, форсунки, ТНВД, ЭБУ. Для двигательной части машины это осмысленный исполнитель в ЕАЭС.', 'https://rpd.kz/', 'high', null),
  ('R1700G', 'Mechon International LLC FZ', 'dealers', 'торговец', 'AE', 'Дубай', 'поставщик оригинальных запчастей Caterpillar и тяжёлой техники; клиенты в 30+ странах', 'Caterpillar, Komatsu, Cummins, Volvo', 'https://mechoninternational.com/', 'sales@mechoninternational.com', '+971 4 572 9843', 'офис Al Qusais Plaza (Дамаск-стрит, оф. 703), регистрация Meydan; доставка в GCC, Африку, Южную Америку, Россию и Казахстан', 'прямо декларирует поставки в Россию и Казахстан и держит русскую версию сайта — то есть российский трафик для них целевой. Отдельно упоминает горные операции (Конго, Перу, Казахстан) и Cat-самосвалы/бульдозеры, значит горная номенклатура в профиле.', 'https://mechoninternational.com/brand/caterpillar-spare-parts-suppliers-dubai', 'high', null),
  ('R1700G', 'Middle East Equipment and Tractors FZE LLC (METRAC)', 'dealers', 'торговец', 'AE', 'Шарджа (SPC Free Zone)', 'экспортёр оригинальных и aftermarket запчастей Caterpillar/Komatsu/Cummins, специализация — горная техника (с 2006 г.)', 'Caterpillar, Komatsu, Cummins, Volvo', 'https://metrac.me/', 'metrac@metrac.me', '+971 50 803 5224', 'заявлена «special export price for all genuine parts»; закупочная сеть под Россию, Казахстан, Африку, Азию и Залив', 'самый прямо заявленный «российский» реэкспортёр оригинала из ОАЭ: на главной странице прямым текстом «doing business with Russia, Kazakhstan, Africa, Asia and the Gulf» и «Redefining Mining since 2006». Для крупных узлов R1700G — первый адрес в дубайском слое.', 'https://metrac.me/', 'high', null),
  ('R1700G', 'Al Burhan Spare Parts TR.', 'dealers', 'торговец', 'AE', 'Шарджа', 'поставщик оригинальных запчастей Caterpillar (более 30 лет на рынке)', 'Caterpillar', 'https://alburhanspares.com/', null, '+971 6 539 0953', 'магазин № 2, Hassan Baba Hassan Building, Caterpillar Road, Industrial Area 3, Шарджа; рабочие часы Пн-Сб 9:00-17:00', 'ассортимент по сайту — двигательная и гидравлическая тема: фильтры, форсунки, водяные насосы, ECM/ECU, гидронасосы, поршни, турбокомпрессоры. Ровно то, что расходуется на C11/C15. Публичная почта на сайте персонифицирована, поэтому не приводим — связь по телефону и через форму.', 'https://alburhanspares.com/cat/caterpillar-genuine-parts/', 'med', null),
  ('R1700G', 'AEI Supplies FZE', 'dealers', 'торговец', 'AE', 'ОАЭ (свободная зона)', 'реселлер оригинальных запчастей Caterpillar и инструмента Cat; также нефтегазовое оборудование', 'Caterpillar', 'https://aeisupplies.com/', 'Info@aeisupplies.com', '+971 50 786 0431', 'глобальная закупочная сеть, логистика по ОАЭ и GCC; есть представительства в США и Пакистане', 'ниша — инструмент Cat и генерация; по подземной ПДМ профиль слабее, чем у METRAC. Держим как резервный адрес для контрольной цены по «сервисному» инструменту и расходке.', 'https://aeisupplies.com/caterpillar-parts-supplier-in-uae/', 'med', null),
  ('R1700G', 'Autoverse (ОАЭ)', 'dealers', 'маркетплейс', 'AE', 'Шарджа', 'онлайн-магазин запчастей Caterpillar с собственным складом; отгрузка по ОАЭ, GCC и Африке', 'Caterpillar', 'https://autoverse.ae/', 'sales@autoverse.ae', '+971 56 610 0995', 'отгрузка со склада в Шардже; КП в течение 24 рабочих часов; цены в AED и USD', 'единственный из дубайского слоя с нормальным онлайн-каталогом по категориям и количествами позиций (воздушные фильтры 483, гидравлические 251, топливные 134, масляные 117, двигатель 949, гидравлика 645 и т.д.) и с русской локалью интерфейса. Удобен для быстрой проверки наличия по конкретному парт-номеру Cat.', 'https://autoverse.ae/caterpillar-genuine-parts-in-dubai/', 'med', null),
  ('R1700G', 'STOPARTS LTD (бренд SORS)', 'dealers', 'торговец', 'TR', 'Истанбул (Бейликдюзю)', 'поставщик оригинальных и aftermarket запчастей для спецтехники, Caterpillar в основном списке брендов', 'Caterpillar, Atlas Copco, Bomag, Hidromek, Hitachi, JCB, Komatsu, Liebherr, Volvo, Cummins, Deutz, Perkins, Carraro, Dana', 'https://sors.tech/', 'info@stoparts.com', '+90 544 969 18 18', 'Adnan Kahveci, Бейликдюзю/Истанбул; работа под заказ', 'полезен именно набором брендов: Carraro и Dana в одном месте с Cat — это трансмиссия и мосты; Perkins/Cummins/Deutz — двигательная часть. Турецкий маршрут в РФ работает, но по практике 2026 г. банковский комплаенс по чувствительным категориям может держать платёж неделями.', 'https://sors.tech/your-global-source-for-quality-caterpillar-spare-parts-genuine-and-aftermarket-solutions-from-stoparts-ltd/', 'med', null),
  ('R1700G', 'Worthy Parts', 'dealers', 'ремонт', 'AU', 'Калгурли (Западная Австралия)', 'разборка горной техники, продажа снятых и восстановленных узлов, глобальная логистика; в разборе была машина Caterpillar R1700G', 'Caterpillar, мультибренд', 'https://www.worthyparts.com/', 'info@worthyparts.com', '+61 8 9021 7182', 'карточка R1700G (наработка 33 000 ч, полная история компонентов и сервиса) — статус Sold; разборы обновляются', 'прямое попадание в нашу машину: у них проходил именно R1700G с полной историей узлов. Для крупных дорогих узлов (мосты, гидротрансформатор, коробка, стрела/ковш) б/у оригинал с историей часто единственный реальный вариант по цене и сроку. Рубрикация сайта по системам машины (Power Train, Steering, Hydraulic, Implements) удобна для запроса по узлу.', 'https://www.worthyparts.com/machine-detail/r1700g-underground-loader-1025/1025/', 'med', null),
  ('R1700G', 'Shandong Tuoxing (tuoxing.com)', 'dealers', 'производитель-неоригинал', 'CN', 'Шаньдун', 'китайский изготовитель подземной техники (скуптрамы, подземные самосвалы) и продавец запчастей к подземным погрузчикам, включая применимость к Cat R1700G', 'собственные + запчасти под Caterpillar', 'https://www.tuoxing.com/application/lhd-caterpillar-r1700g', null, null, 'не заявлено; торгует также через Alibaba', 'слабый источник: страница по R1700G — маркетинговая, технические данные (C11, 242 кВт, 15 т, 39 000 кг) переписаны из брошюры Cat. Значение только одно: подтверждает, что китайский неоригинал под R1700G существует как товарная категория. Парт-номера с такой страницы брать нельзя.', 'https://www.tuoxing.com/application/lhd-caterpillar-r1700g', 'low', null),
  ('R1700G', 'Snabus.ru', 'dealers', 'маркетплейс', 'RU', '—', 'справочник характеристик спецтехники (13 500+ единиц), карточка CAT R1700G в разделе «Погрузочно-доставочные машины для подземных работ»', 'мультибренд', 'https://www.snabus.ru/lhd-loaders/cat-lhd-loaders/caterpillar-r1700g-lhd-loader/', null, null, '—', 'не поставщик, а справочный источник ТТХ на русском по R1700G. Держим в списке, чтобы отделить справочники от реальных каналов: в поисковой выдаче по «запчасти R1700G» такие сайты занимают первые места и создают ложное ощущение предложения.', 'https://www.snabus.ru/lhd-loaders/cat-lhd-loaders/caterpillar-r1700g-lhd-loader/', 'low', null),
  ('R1700G', 'Costex Tractor Parts (CTP / Costex Corporation)', 'aftermarket', 'производитель-неоригинал', 'US', 'Майами (Доral), Флорида', 'крупнейший в США производитель/поставщик неоригинала для Caterpillar и Komatsu, бренд CTP', 'CTP, Costex', 'https://www.costex.com/', null, null, 'склады Майами и Даллас; отгрузка в 140 стран; в РФ — через дистрибьюторов (Аймашинери, ЗИПТЕХ-СЕРВИС, 74parts)', 'Закрывает по узлам R1700G: комплекты капремонта ДВС (3304/3306/3116/C7/C9/C13), фрикционные и тормозные диски, диски ПКП, ремкомплекты гидроцилиндров, РВД и шланги, турбокомпрессоры, подшипники, ремни, режущие элементы. Ровно C11/C15 ACERT в публичном перечне двигателей не заявлен — проверять по номеру. 45 000+ номенклатуры, склад 380 тыс. кв. футов.', 'https://www.costex.com/about-us', 'med', null),
  ('R1700G', 'Interstate-McBee, LLC', 'aftermarket', 'производитель-неоригинал', 'US', 'Кливленд, Огайо', 'производитель запчастей ДВС для Caterpillar (собственное производство прокладок в Кливленде)', 'Interstate-McBee', 'https://interstate-mcbee.com/caterpillar_parts/', null, '+1 216-881-0015', 'склад США; в РФ представителя нет — через параллельный импорт/посредников', 'Прямое попадание в двигатель R1700G: линейка по C11/C15 и 3400. Гильзы, поршни, кольца, вкладыши, топливная (форсунки, ТНВД, распылители), клапанный механизм, водяные насосы, прокладки и комплекты прокладок, комплекты капремонта (in-frame/out-of-frame). ISO 9001:2015, 20 000+ позиций, 70 лет на рынке.', 'https://interstate-mcbee.com/caterpillar_parts/', 'high', null),
  ('R1700G', 'IPD (Industrial Parts Depot, LLC)', 'aftermarket', 'производитель-неоригинал', 'US', 'Торранс, Калифорния', 'производитель поршневой группы и гильз для Caterpillar, premium-эконом уровня OEM', 'IPD, IPDSteel', 'https://www.ipdparts.com/applications/caterpillar/', null, '+1 310-530-1900', 'склад США; в РФ представителя нет', 'Поршни (в т.ч. цельностальные IPDSteel, которых нет у Cat), гильзы с патентованным Crevice Seal, кольца, комплекты цилиндров, in-frame/out-of-frame наборы. Отдельная литература по C15 и 3400/C15 — это база двигателя R1700G (C11/C15 ACERT). Уровень OEM-grade и выше по заявлению производителя.', 'https://www.ipdparts.com/literature/c15/', 'high', null),
  ('R1700G', 'PAI Industries, Inc.', 'aftermarket', 'производитель-неоригинал', 'US', 'Суони, Джорджия', 'производитель неоригинальных деталей тяжёлых дизелей (в т.ч. Caterpillar)', 'PAI', 'https://www.paiindustries.com/', null, '+1 770-822-1000', 'склад США, дилерская сеть; в РФ представителя нет', 'Поршни, гильзы, вкладыши, комплекты прокладок, детали привода — для платформ Cummins, Detroit Diesel, Caterpillar. Основана в 1973. Уровень — эконом/средний, дешевле OEM. Применимость к C11/C15 нужно подтверждать по каждому номеру, публичного каталога по горной технике нет.', 'https://www.truckpartsandservice.com/aftermarket-truck-parts-suppliers/driveline-transmission/clutches-related-parts/company/14982628/pai-industries-inc', 'med', null),
  ('R1700G', 'Reliance Power Parts (Nivel Heavy Duty)', 'aftermarket', 'производитель-неоригинал', 'US', 'Уинчестер, Индиана', 'производитель/маркетолог неоригинала по ремонту дизелей «все марки», включая Caterpillar', 'Reliance', 'https://www.reliancepowerparts.com/', null, '+1 800-342-2545', 'несколько складов в США, продажи только через дилеров; в РФ дилера нет', 'Каталог 100 000+ позиций на 5 000+ применений и 50+ OEM, Caterpillar заявлен прямо. Детали ремонта ДВС: поршневая, прокладки, топливная, охлаждение. Заказ — только через авторизованного дилера (нужна учётная запись), это осложняет разовую закупку из РФ.', 'https://www.reliancepowerparts.com/about-us/about-reliance', 'high', null),
  ('R1700G', 'Weir ESCO (ESCO Group LLC)', 'aftermarket', 'производитель-неоригинал', 'US', 'Портленд, Орегон', 'мировой производитель износостойкого инструмента (GET) для ковшей погрузчиков и экскаваторов', 'ESCO, Ultralok, Nemisys, MaxDRP', 'https://www.global.weir/product-catalogue/construction-wear-parts/wheel-loader/', null, null, 'сеть дистрибьюторов Weir; поставок в РФ после 2022 официально нет', 'Ключевое для ПДМ: зубья и адаптеры ковша колёсного погрузчика, губы Loadmaster, бокорезы, защиты. MaxDRP прямо позиционируется как замена коронок Caterpillar со шкворневым (side-pin) креплением — это система R1700G. Уровень выше OEM по стойкости, цена соответствующая.', 'https://www.global.weir/product-catalogue/construction-wear-parts/wheel-loader/', 'med', null),
  ('R1700G', 'Hensley Industries, Inc. (Komatsu Group)', 'aftermarket', 'производитель-неоригинал', 'US', 'Даллас, Техас', 'производитель GET, зубьев и адаптеров, совместимых с системами Caterpillar', 'Hensley, XS, KMAX', 'https://www.hensleyind.com/', null, '+1 972-241-2321', 'дистрибьюторы США/ЕС; в РФ поставок нет (входит в Komatsu Group)', 'Зубья, адаптеры, бокорезы, защиты кромки без молотка (hammerless). Совместимость с Cat в каталогах дистрибьюторов указывается через X-серию (X156, X295 и пр.). Для R1700G применим по системе зубьев ковша погрузчика; конкретную серию под коронки Cat нужно сверять по чертежу.', 'https://www.hensleyind.com/contact/', 'med', null),
  ('R1700G', 'Metalogenia S.A. (MTG)', 'aftermarket', 'производитель-неоригинал', 'ES', 'Монсон / Барселона', 'испанский производитель GET и систем защиты ковша, патентованные зубья и адаптеры', 'MTG, MTG Systems, ProMet, StarMet', 'https://mtgcorp.com/en/', null, '+34 93 741 70 00', '300+ дилеров в 60 странах; отдельный офис США (+1 281 872 15 00); поставки в РФ — через третьи страны', 'Зубья, адаптеры, защита кромки и бортов ковша, бронеэлементы для горной и строительной техники. Прямо заявлена совместимость с оригинальными стойками рыхлителя Caterpillar. Собственная марка стали (MTG Steels) и своё литьё — уровень OEM-grade.', 'https://mtgcorp.com/en/contact', 'med', null),
  ('R1700G', 'Combi Wear Parts AB', 'aftermarket', 'производитель-неоригинал', 'SE', 'Люнгбю (литейное) / Кристинехамн', 'швейцарский по качеству производитель систем износа для погрузчиков и экскаваторов, своё литейное производство', 'Combi, C-REX', 'https://www.combiwearparts.com/', 'info@combiparts.com', '+46 550 410 550', 'дилеры Европы (осн. рынки Германия, США); в РФ дилера нет', 'Система C-REX разработана под колёсные погрузчики 12–55 т — это ровно класс R1700G (эксплуатационная масса около 25–30 т с ковшом 6 куб. м). Зубья, защиты губы, бортов и пяток ковша, безмолотковый механический замок. Собственная литейка, ISO 14001, оптимизированные марки стали.', 'https://www.combiwearparts.com/about-us/', 'med', null),
  ('R1700G', 'USCO S.p.A. (USCO ITR Group)', 'aftermarket', 'производитель-неоригинал', 'IT', 'Модена', 'крупнейший в мире поставщик неоригинала для землеройной техники, производство под маркой ITR', 'ITR, USCO', 'https://www.usco.it/en/', null, '+39 059 9780111', 'заводы Италия/Германия/Испания/США/Бразилия/Китай, склады в ЕС; в РФ официального склада нет', 'Из 50 000+ позиций для R1700G полезны именно repair parts, а не ходовая: пальцы и втулки шарниров, сальники и ремкомплекты гидроцилиндров, GET, крепёж, элементы рулевого и сочленения. USCO с 1989 начинал именно как специалист по Caterpillar. Ходовая часть (гусеницы) к колёсной ПДМ неприменима.', 'https://www.usco.it/en/the-group/history/', 'med', null),
  ('R1700G', 'Italtractor ITM S.p.A. (ITM Group)', 'aftermarket', 'производитель-неоригинал', 'IT', 'Вальсамоджа (Болонья)', 'производитель ходовой части и GET, заводы в 8 странах', 'ITM, ITR', 'https://www.group-itm.com/en/itm-group/', null, null, 'сеть дилеров, производство Италия/Германия/Испания/США/Бразилия/Китай/Австралия + СП в Индии', 'Основная продукция — гусеничная ходовая, для колёсной ПДМ R1700G неприменима. Полезен только сегмент GET и литые износостойкие элементы. Включать в закупку R1700G нужно осознанно, чтобы не платить за нерелевантную номенклатуру. 1 700 сотрудников, основан в 1957.', 'https://www.group-itm.com/en/itm-group/', 'low', null),
  ('R1700G', 'Berco S.p.A. (thyssenkrupp Forged Technologies)', 'aftermarket', 'производитель-неоригинал', 'IT', 'Коппаро (Феррара)', 'OEM и aftermarket производитель ходовых систем, отдельная компания Berco Aftermarket в Болонье', 'Berco (Platinum / Original / Service)', 'https://www.berco.com/', 'info.berco@thyssenkrupp.com', '+39 0532 864300', '14 производств; Berco Aftermarket (Болонья, via Altabella 17) — склад под глобальный aftermarket; в РФ представителя нет', 'Для R1700G почти нерелевантен: звёзды, направляющие, катки, цепи, башмаки — гусеничная тема. Держать в списке стоит как поставщика ковки и литья (пресс 32 000 т) на случай нестандартных осей/пальцев. Указан в задании, поэтому оставлен с честной низкой применимостью.', 'https://www.berco.com/group/our-locations/', 'low', null),
  ('R1700G', 'Blumaq S.A.', 'aftermarket', 'производитель-неоригинал', 'ES', 'Ла-Валь-д''Уишо (Кастельон)', 'производитель и дистрибьютор альтернативных запчастей Caterpillar, есть представительства в РФ', 'Blumaq', 'https://www.blumaq.com/', null, null, 'склад 6 000 кв. м, 90 000+ номеров; представительства Москва и Самара (а также Краснодар, Ростов-на-Дону, Волгоград, Астрахань, Мин. Воды, Сочи), логистика Измир/Анкара/Анталья', 'Единственный из крупных европейских неоригиналов с заявленным присутствием в РФ. По R1700G закрывает фрикционные диски тормозной системы Caterpillar, уплотнения, детали ДВС, гидравлику, GET. Купил итальянского производителя шасси Campadelli & Trentini, то есть часть номенклатуры — собственное производство, часть — торговля. ISO 9001:2015.', 'https://www.blumaq.com/rus/frikcionnye-diski-cat/', 'med', null),
  ('R1700G', 'Baldwin Filters (подразделение Parker Hannifin)', 'aftermarket', 'производитель-неоригинал', 'US', 'Керни, Небраска', 'вертикально интегрированный производитель фильтров для внедорожной техники', 'Baldwin', 'https://www.baldwinfilters.com/', null, null, 'производство Керни (NE) и Янктон (SD); в РФ — через дистрибьюторов фильтров', 'Закрывает ПОЛНЫЙ фильтровый набор R1700G по официальному кросс-листу Caterpillar: 423-8524 -> BF1397-SP/BF1399SP (сепаратор), 1R-0762 -> BF7753 (топливный), 1R-1808 -> B7299/B7402/B7507 (масляный ДВС), 1R-0722 -> PT83/PT8461 (гидравлика), 6I-2510 -> RS3515 и 132-7167 -> RS3514 (воздушные), 231-0167 -> RS3542 (кабина). ISO 9001 / TS 16949.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'high', null),
  ('R1700G', 'Donaldson Company, Inc.', 'aftermarket', 'производитель-неоригинал', 'US', 'Блумингтон, Миннесота', 'мировой производитель фильтрации для внедорожной и горной техники', 'Donaldson, Donaldson Blue', 'https://www.donaldson.com/', null, null, '140+ локаций на 6 континентах; в РФ работает через дистрибьюторов', 'Полный набор R1700G по кросс-листу Caterpillar: 423-8524 -> P550900, 1R-0762 -> P550625, 1R-1808 -> P551808/P550788/P554005, 1R-0722 -> P550575/P555461/P164241, 6I-2510 -> P532510, 132-7167 -> P532509, 231-0167 -> P827653. Основан 1915, 10 000+ сотрудников.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'high', null),
  ('R1700G', 'Fleetguard (Atmus Filtration Technologies, ранее Cummins Filtration)', 'aftermarket', 'производитель-неоригинал', 'US', 'Нэшвилл, Теннесси', 'производитель фильтров для грузовой, строительной и горной техники', 'Fleetguard', 'https://www.cummins.com/en-na/eu/parts/fleetguard', null, null, 'глобальная дистрибуция; в РФ доступен через дистрибьюторов Cummins-сервиса', 'Полный набор R1700G по кросс-листу Caterpillar: 423-8524 -> FS20007, 1R-0762 -> FF5624, 1R-1808 -> LF3374/LF3472/LF3566, 1R-0722 -> HF6202, 6I-2510 -> AF25138M/AF25035, 132-7167 -> AF25137M/AF25034M, 231-0167 -> AF25555/AF25588. Бренд с 1958, с 2023 выделен в Atmus.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'high', null),
  ('R1700G', 'WIX Filters', 'aftermarket', 'производитель-неоригинал', 'US', 'Гастония, Северная Каролина', 'производитель фильтров, широко представлен в кросс-листах Caterpillar', 'WIX, NAPA Gold', 'https://www.wixfilters.com/', null, null, 'дистрибуция через автокомпоненты; в РФ есть каналы', 'Полный набор R1700G по кросс-листу Caterpillar: 423-8524 -> 33607, 1R-0762 -> 33640/533640, 1R-1808 -> 51792/51792XE/51792MP, 1R-0722 -> 51194/57197, 6I-2510 -> 46589, 132-7167 -> 46742, 231-0167 -> 46671. Дешевле Baldwin/Donaldson, качество эконом-средний.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'high', null),
  ('R1700G', 'MANN+HUMMEL GmbH', 'aftermarket', 'производитель-неоригинал', 'DE', 'Людвигсбург', 'европейский производитель фильтров, каталог покрывает Caterpillar', 'MANN-FILTER', 'https://www.mann-hummel.com/', null, null, 'дистрибуция ЕС/РФ через автокомпонентные сети', 'По кросс-листу Caterpillar закрывает часть набора R1700G: 132-7167 -> C32160 (воздушный), 1R-0762 -> WK9058 (топливный), 1R-1808 -> WD1314518 (масляный), 231-0167 -> C142021 (кабина). Сепаратор 423-8524 и гидравлика 1R-0722 в кросс-листе за MANN не числятся — их искать у Baldwin/Donaldson/Fleetguard.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'high', null),
  ('R1700G', 'Luber-finer (Champion Laboratories / First Brands Group)', 'aftermarket', 'производитель-неоригинал', 'US', 'Албион, Иллинойс', 'производитель фильтров для тяжёлой техники', 'Luber-finer, Champion Labs', 'https://www.luberfiner.com/', null, null, 'дистрибуция США; в РФ точечно', 'По кросс-листу Caterpillar: 423-8524 -> LFF6771, 1R-0762 -> LFF5804, 1R-1808 -> LFP4005RN; под маркой Champion Laboratories также 132-7167 -> LAF4509, 231-0167 -> LAF7653, 1R-0722 -> LH5461. Позиция — эконом.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'high', null),
  ('R1700G', 'Hengst SE', 'aftermarket', 'производитель-неоригинал', 'DE', 'Мюнстер', 'немецкий производитель фильтров, OEM-поставщик и aftermarket', 'Hengst', 'https://www.hengst.com/', null, null, 'дистрибуция ЕС; в РФ через посредников', 'По кросс-листу Caterpillar частично закрывает R1700G: 1R-0722 -> E48H (гидравлика), 1R-0762 -> H264WK (топливный), 231-0167 -> E571L (кабина), 6I-2510 -> LAF4510. Масляный 1R-1808 и сепаратор 423-8524 за Hengst не указаны.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'high', null),
  ('R1700G', 'SAKURA Filter', 'aftermarket', 'производитель-неоригинал', 'JP', null, 'японский бренд фильтров, распространён в Азии и на вторичном рынке горной техники', 'SAKURA', 'https://www.sakura-filter.com/', null, null, 'производство и склады в Азии; в РФ через азиатские каналы', 'По кросс-листу Caterpillar закрывает воздушную группу R1700G: 6I-2510 -> A5563, 132-7167 -> A5564, 231-0167 -> A8506 (кабина). По топливу, маслу и гидравлике в листе не заявлен. Юрлицо и завод под этой маркой не проверены — нужна сверка перед закупкой.', 'http://s7d2.scene7.com/is/content/Caterpillar/CM20231004-c3763-43efb', 'med', null),
  ('R1700G', 'HIFI FILTER (группа SOFIMA)', 'aftermarket', 'производитель-неоригинал', 'FR', 'Вьё-Тан (Эльзас)', 'европейский производитель фильтров для строительной и горной техники, полные кросс-таблицы по Caterpillar', 'HIFI FILTER, SOFIMA', 'https://www.hifi-filter.com/', null, null, 'заводы во Франции и Италии, дистрибуция ЕС; в РФ через посредников', 'Заявлены прямые замены фильтров Caterpillar, включая гидравлику и топливо; типоразмеры под 1"-12 UNF (масляные) совпадают с cat-навёрткой. Конкретные номера HIFI против нашего набора R1700G по официальному документу Caterpillar не подтверждены — в кросс-листе Cat марки HIFI нет, нужна сверка через собственный подборщик HIFI.', 'https://sonafilter.com/caterpillar-replacement-filter-cross-reference/', 'med', null),
  ('R1700G', 'Parker Hannifin Corporation', 'aftermarket', 'производитель-неоригинал', 'US', 'Кливленд, Огайо', 'производитель рукавов, фитингов и уплотнений, в т.ч. для подземной горной гидравлики', 'Parker, GlobalCore, ToughCover, Coalmaster', 'https://www.parker.com/', null, null, 'сеть ParkerStore; в РФ — через локальных сборщиков РВД по лицензии/оснастке', 'Для R1700G закрывает изготовление РВД взамен оригинальных: серия 387 GlobalCore 3000 psi в размерах -4…-32, покрытие ToughCover (стойкость к истиранию в 80 раз выше стандарта) и SuperTough, плюс шахтная серия Coalmaster — прямо для подземной абразивной среды. Это то место, где неоригинал дешевле и доступнее оригинала без потери класса.', 'https://www.constructionequipment.com/equipment-maintenance-and-repair/hydraulic-hose/product/10711251/parker-hannifin-coalmaster-tough-cover-mining-hose', 'med', null),
  ('R1700G', 'HYDAC International GmbH', 'aftermarket', 'производитель-неоригинал', 'DE', 'Зульцбах/Саар', 'производитель фильтроэлементов и гидрокомпонентов, отдельное направление mining', 'HYDAC', 'https://www.hydac.com/en-us/industry-solutions/mining/', null, null, 'глобальная сеть; в РФ есть локальные поставщики аналогов элементов HYDAC', 'Заявляет замены более 70 000 сторонних изделий от 60+ производителей — то есть способен изготовить аналог гидравлического/смазочного элемента Caterpillar по чертежу и посадке. Для R1700G это гидравлика (аналог 1R-0722) и смазочный фильтр 150 мкм (211-3342). Конкретных кросс-номеров против нашего набора не видел — нужна заявка в HYDAC с оригинальным номером.', 'https://www.hydac.com/en-us/industry-solutions/mining/', 'med', null),
  ('R1700G', 'Trelleborg Sealing Solutions', 'aftermarket', 'производитель-неоригинал', 'SE', 'Треллеборг', 'производитель уплотнений для строительной и горной техники', 'Trelleborg, Turcon, Zurcon', 'https://www.trelleborg.com/en/seals/your-industry/construction-and-mining-equipment/mining-trucks', null, null, 'глобальная сеть; в РФ поставки ограничены, аналоги делают локальные заводы', 'Уплотнения гидроцилиндров (штоковые и поршневые манжеты, грязесъёмники), радиальные манжеты, подшипники скольжения — та номенклатура, которая на R1700G уходит в ремкомплекты стрелы, ковша, рулевых цилиндров и сочленения. Для конкретной машины подбор по посадочным размерам, а не по номеру Cat.', 'https://www.trelleborg.com/en/seals/your-industry/construction-and-mining-equipment/mining-trucks', 'med', null),
  ('R1700G', 'Gates Corporation', 'aftermarket', 'производитель-неоригинал', 'US', 'Денвер, Колорадо', 'производитель рукавов, ремней и шлангов для гидравлики', 'Gates, MegaSys', 'https://www.gates.com/us/en/hydraulics.html', null, null, 'дистрибуция глобальная; в РФ представлены ремни и шланги через автокомпонентные каналы', 'Назван в задании как поставщик гидравлики. Страница гидравлики Gates при загрузке отдала почти пустой каркас (786 символов текста), поэтому по факту НИЧЕГО конкретного о покрытии R1700G не подтверждено. Строку оставляю как задел: направление верное (РВД, ремни привода вентилятора и компрессора), но требует отдельной проверки по каталогу.', 'https://www.gates.com/us/en/hydraulics.html', 'low', null),
  ('R1700G', 'Kastaş Sealing Technologies A.Ş.', 'aftermarket', 'производитель-неоригинал', 'TR', 'Измир', 'турецкий производитель гидравлических и пневматических уплотнений полного цикла', 'Kastas, SmartSeal, K-Flon', 'https://www.kastas.com/en', null, null, 'производство Измир 40 000 кв. м, склад Kastaş Europe GmbH (Германия) с отгрузкой за 24 ч; в РФ каталог Kastas ведут локальные поставщики (например КРПМС)', '10 000+ стандартных уплотнений, направление — строительная, горная и сельхозтехника. Полный цикл: смесь резины, термопласты, пресс-формы, ИСО 9001 и TS/16949, FEA-расчёт. Для R1700G это ремкомплекты гидроцилиндров и вращающихся соединений — подбор по посадкам. Экспорт больше 50 %.', 'https://www.kastas.com/en/corporate/about-us', 'high', null),
  ('R1700G', 'Megatech Construction Machinery Spare Parts Ltd. (ранее Yesilova)', 'aftermarket', 'производитель-неоригинал', 'TR', 'Стамбул', 'первая турецкая компания, специализированная именно на производстве неоригинала для Caterpillar/Komatsu/Volvo', 'Megatech', 'https://www.megatech-tr.com/', 'info@megatech-tr.com', '+90 216 499 63 95', 'закрытый склад 1 200 кв. м в Стамбуле, производство на субподрядных заводах (около 100 рабочих); экспорт в Россию заявлен прямо', 'Наиболее реалистичный канал неоригинала для R1700G в обход западных ограничений: сами заявляют экспорт в США, Европу, Африку, Россию, Австралию и Средний Восток с 1980 года. ISO 9001 (UKAS/AJA), продукция заявлена полностью взаимозаменяемой с OEM. Начинать переписку с sales@megatech-tr.com и списка номеров Cat.', 'https://www.megatech-tr.com/en/aboutUs.asp', 'high', null),
  ('R1700G', 'Gürkaylar Group (GSE — Gurkaylar Spare Parts)', 'aftermarket', 'производитель-неоригинал', 'TR', 'Стамбул', 'турецкий производитель/поставщик запчастей турецкого изготовления для Caterpillar и Komatsu', 'Gurkaylar, GSE', 'https://en.gurkaylar.com/', 'gse@gurkaylar.com', '+90 212 482 04 27', 'склад Стамбул; поставки в СНГ через турецкую логистику', 'Прямо позиционирует «Turkish made spare parts for Caterpillar and Komatsu machinery» — то есть собственное/контрактное производство в Турции, а не перепродажа. Номенклатура по горной технике на странице не детализирована: нужен запрос перечня по узлам R1700G (гидравлика, трансмиссия, ходовая, кабина).', 'https://en.gurkaylar.com/news/turkish-made-spare-parts-for-caterpillar-and-komatsu-machinery', 'med', null),
  ('R1700G', 'ValuePart Turkey (ранее Yesilova Ltd., СП с ValuePart Europe)', 'aftermarket', 'производитель-неоригинал', 'TR', 'Стамбул', 'турецкий производитель-экспортёр неоригинала для Caterpillar и Komatsu', 'ValuePart, VPI', 'https://www.valuepart.com/', null, null, 'производство и экспорт с 1980; после 2008 в группе ValuePart Europe S.p.A.', 'Заявленное покрытие шире турецких конкурентов: ходовая, GET, детали ДВС, рамы, гидрокомпоненты, привод и трансмиссия — последние два пункта важны для ПДМ (ПКП, ГТР, мосты). Официальный сайт valuepart.com.tr и valuepart.com/about при обращении не отдались, поэтому данные только по каталогу экспортёров — проверять напрямую.', 'https://www.turkishexporter.net/en/companies/valuepart-turkey_N76762', 'low', null),
  ('R1700G', 'Stoparts Ltd.', 'aftermarket', 'торговец', 'TR', 'Бейликдюзю, Стамбул', 'турецкий поставщик оригинала и качественного неоригинала Caterpillar', 'Caterpillar (genuine), aftermarket', 'https://www.stoparts.com/', 'info@stoparts.com', null, 'склад Стамбул, отгрузка на экспорт', 'Не завод, а трейдер — полезен как быстрый канал на разовые позиции и как источник сверки цен по Турции. Для R1700G ценность в том, что турецкие трейдеры свободно покупают оригинал Cat и отгружают в СНГ; наценка компенсируется отсутствием ограничений.', 'https://sors.tech/your-global-source-for-quality-caterpillar-spare-parts-genuine-and-aftermarket-solutions-from-stoparts-ltd/', 'med', null),
  ('R1700G', 'SEIGO Machinery Equipment Co., Ltd.', 'aftermarket', 'производитель-неоригинал', 'CN', 'Гуандун', 'китайский производитель гидроцилиндров, есть отдельная линейка под CAT R1700 (подземная ПДМ)', 'SEIGO', 'https://seigomachinery.com/', null, null, 'завод в Гуандуне, 30 лет производства, ISO 9001; экспорт по миру, в РФ через китайскую логистику', 'САМАЯ прямая находка по R1700G среди неоригинала: в каталоге отдельные карточки цилиндров подъёма и опрокидывания для CAT R1700 LHD (в заголовках карточек фигурируют номера 541-8382 hoist и 180-9367 tilt, для R1700 II со ссылкой на 9EL-0626). Штоки 42CrMo4 с индукционной закалкой, уплотнения NOK/Parker, испытание 1,5× рабочего давления, гарантия 12 мес / 2000 ч. Требуют полный серийный номер машины для подбора. Номера взяты из выдачи по страницам каталога, сами страницы отдаются через JS — перед закупкой открыть карточку и сверить.', 'https://seigomachinery.com/product/541-8382-cat-r1700-lhd-hoist-cylinder/', 'med', null),
  ('R1700G', 'Ningbo Sanjin Engineering Machinery Co., Ltd (NBSJ)', 'aftermarket', 'производитель-неоригинал', 'CN', 'Нинбо, Чжэцзян', 'литейный завод GET: зубья и адаптеры ковша, в т.ч. систем Caterpillar', 'NBSJ', 'https://www.nbsj-get.com/', null, '+86 574 82830922', 'собственный завод 36 000 кв. м, 8 000 т/год; экспорт в Россию, Казахстан, Монголию и 55+ стран', 'Льют по выплавляемым моделям (lost wax investment casting) зубья Cat J-серии (в каталоге, например, 1U3352RC и 9W8552RC), адаптеры, зубья рыхлителя, режущие кромки. Для R1700G это расходник номер один: зубья и адаптеры ковша. Экспорт в РФ/КЗ заявлен прямо — значит есть отработанная логистика и документы. Уровень — эконом/средний, стойкость ниже ESCO, цена в разы ниже. Публичный контакт на сайте — личный адрес менеджера, поэтому не приведён: писать через форму на сайте или на общий ящик, запрошенный отдельно.', 'https://www.nbsj-get.com/about-us', 'high', null),
  ('R1700G', 'Jining Kunhang Hydraulic Machinery Co., Ltd.', 'aftermarket', 'производитель-неоригинал', 'CN', 'Цзинин, Шаньдун', 'производитель гидравлики для строительной техники, работает с Россией', 'Kunhang', 'https://jnkunhang.en.made-in-china.com/', null, null, 'завод: Workshop 7, Dongyi Industrial Park, Liuxing Street, High Tech Zone, Jining; долгосрочные клиенты в РФ заявлены прямо', 'Гидронасосы, редукторы хода и бортовые, поворотные мотор-редукторы, главные распределители, центральные (поворотные) коллекторы и гидравлические уплотнения; Caterpillar в списке поддерживаемых марок. Для R1700G релевантны насосы, распределители, ремкомплекты уплотнений; редукторы хода — нет (машина колёсная с мостами). OEM/ODM. Заказ через made-in-china, MOQ от 1 шт.', 'https://jnkunhang.en.made-in-china.com/', 'high', null),
  ('R1700G', 'Jining Haochang Group Co., Ltd.', 'aftermarket', 'производитель-неоригинал', 'CN', 'Цзинин, Шаньдун', 'производитель/поставщик гидроприводов для строительной и ГОРНОЙ техники', 'Haochang', 'https://haochanggroup.en.made-in-china.com/', null, null, 'основан в 2006, ISO 9001, сеть продаж в 100+ странах', 'Гидромоторы, бортовые редукторы, поворотные моторы, редукторы, гидравлические распределители, электрика; прямо заявлена применимость к Caterpillar наряду с Komatsu, Hitachi, Liebherr. Сами указывают горную технику как целевой сегмент — это ближе к ПДМ, чем чистые экскаваторщики. Продукция двух уровней: Genuine и OEM quality.', 'https://haochanggroup.en.made-in-china.com/', 'high', null),
  ('R1700G', 'Quanzhou Fuwei Machinery Co., Ltd', 'aftermarket', 'производитель-неоригинал', 'CN', 'Нань-ань, Цюаньчжоу, Фуцзянь', 'литейно-механический завод: зубья ковша, опорно-поворотные, катки, гидроцилиндры', 'Fuwei', 'https://fwmach.en.made-in-china.com/', null, null, 'адрес завода: Sijia Industrial Zone, Xiamei Town, Nan''an City; основные рынки включают Восточную Европу; Incoterms FOB/EXW/CFR/CIF, оплата T/T, D/P', 'Из номенклатуры для R1700G годятся зубья ковша, опорно-поворотные подшипники, гидроцилиндры (oil cylinder) и двигатель/насосы как торговая позиция. MOQ низкие — от 1–2 шт. по карточкам товара. Экспортная история с 2021, то есть молодой поставщик: проверять образцами.', 'https://fwmach.en.made-in-china.com/', 'med', null),
  ('R1700G', 'Hangzhou Henli Friction Material Co., Ltd.', 'aftermarket', 'производитель-неоригинал', 'CN', 'Ханчжоу, Чжэцзян', 'один из крупнейших в Китае производителей фрикционных дисков и накладок, в т.ч. для строительной техники', 'Henli', 'https://hzhlzxf.en.made-in-china.com/', null, null, 'Manufacturer/Factory, ISO 9001 / ISO 14064 / ISO 20000; продажи фрикционных дисков в Европу около 1 млн USD/год', 'Фрикционные и стальные диски, тормозные диски, фрикционный материал, детали трансмиссий строительной и сельхозтехники. Для R1700G это ровно тот узел, где оригинал дорогой и расходуемый: диски ПКП и дисковые мокрые тормоза мостов. Caterpillar в списке поддерживаемых платформ.', 'https://hzhlzxf.en.made-in-china.com/', 'high', null),
  ('R1700G', 'FRICWEL AUTOMOTIVE LIMITED', 'aftermarket', 'производитель-неоригинал', 'CN', 'Ханчжоу (Сяошань), Чжэцзян', 'производитель фрикционных материалов с 1992, есть готовые позиции под номера Caterpillar', 'Fricwel', 'https://fricwel.en.made-in-china.com/', null, null, 'завод 25 000+ кв. м, около 10 млн изделий в год; рынки включают Восточную Европу; есть русскоговорящий менеджер', 'В каталоге прямо есть фрикционные диски под номера Caterpillar (например карточки 1P4110 и мокрый тормозной/трансмиссионный диск 551717). MOQ 100–300 шт. на позицию, срок 1 мес в низкий сезон и 1–3 мес в высокий — для R1700G это закупка партией на парк, а не на одну машину. Наличие русскоязычного менеджера снижает трение переписки.', 'https://fricwel.en.made-in-china.com/', 'high', null),
  ('R1700G', 'Aili (Yichun) precision casting', 'aftermarket', 'производитель-неоригинал', 'CN', 'Ичунь, Цзянси', 'литейный завод GET, зубья ковша под системы Caterpillar (J-серия)', 'Aili', 'https://www.ailiparts.com/', null, null, '40 лет литейного опыта, мощность 24 000 т/год, порты Нинбо и Шанхай', 'Зубья ковша ковкой и точным литьём под Caterpillar J-серию (в карточке — J200 для мини-экскаватора), режущие элементы. Для R1700G нужен крупный типоразмер, поэтому запрашивать именно погрузочную серию под коронки Cat со шкворнем. Уровень эконом, контроль качества — по образцам. На странице указан только мобильный номер менеджера, поэтому не приведён: выходить через форму на сайте.', 'https://www.ailiparts.com/bucket-teeth-manufacturer-rock-forging-yellow-or-black-bucket-teeth-for-mini-excavator-caterpillar-j200-products/', 'med', null),
  ('R1700G', 'ООО «Техно-ГМ»', 'aftermarket', 'производитель-неоригинал', 'RU', 'Челябинск', 'российский завод: фрикционные и тормозные диски, уплотнения, гидроцилиндры, редукторы для импортной спецтехники', 'Техно-ГМ', 'https://texno-gm.com/', 'z1@texno-gm.com', '+7 (351) 200-98-19', 'своё производство, Челябинск, Плотничный пер. 16; цены завода-производителя, работа по РФ', 'Самая полная российская связка по узлам R1700G среди найденных: фрикционные и тормозные диски, производство уплотнений и комплектующих гидроцилиндров, производство гидроцилиндров, хонингованных труб до 15 м, редукторов и запчастей для карьерных самосвалов и экскаваторов. В списке поддерживаемых марок прямо KOMATSU, TEREX, CATERPILLAR, HITACHI. Годится и как изготовитель по чертежу/образцу.', 'https://texno-gm.com/product/tormoznaya-sistema/friktsionnye-diski/', 'high', null),
  ('R1700G', 'АО «Уральский завод РТИ» (Урал-РТИ)', 'aftermarket', 'производитель-неоригинал', 'RU', 'Екатеринбург', 'изготовление РВД и РТИ по чертежам и образцам, отдельный раздел по Caterpillar', 'Урал-РТИ', 'https://ural-rti.ru/', 'rti@ural-rti.ru', '+7 958 578-05-89', 'наличие на складе + изготовление; ремонт РВД; отгрузка по регионам РФ', 'Прямо заявляют изготовление аналогов импортных гидравлических рукавов Komatsu, Caterpillar, JCB, Hitachi, Volvo без потери качества и существенно дешевле. Испытание давлением с превышением рабочего в 1,5–2 раза по ГОСТ 6286-73 и DIN EN 853. Для R1700G это самая частая и самая срочная позиция — РВД делают по образцу за дни, а не за месяцы.', 'https://ural-rti.ru/rukava-ysokogo-davleniya-s-fitingami-dlya-otechestvennoy-i-importnoy-tekhniki/rvd-dlya-ekskavatorov-i-buldozerov-caterpillar/', 'high', null),
  ('R1700G', 'ООО ТД «РВД»', 'aftermarket', 'производитель-неоригинал', 'RU', 'Челябинск', 'завод рукавов высокого давления полного технологического цикла', 'ТД РВД', 'https://ooorvd.ru/', 'zakaz@tdrvd.ru', '8 (800) 550-66-17', 'мощность до 40 000 готовых РВД в месяц; отгрузка по РФ', 'Объём делает поставщика пригодным под парк техники, а не под единичный ремонт: закрывает разовую потребность по всей гидравлике R1700G (стрела, ковш, рулевое, сочленение, тормоза) при наличии образцов или чертежей. Промышленные рукава и гидравлические шланги — в той же линейке.', 'https://ooorvd.ru/', 'high', null),
  ('R1700G', 'ГК «Гидроимпульс»', 'aftermarket', 'производитель-неоригинал', 'RU', null, 'производство РВД по чертежам, каталожным номерам и образцам', 'Гидроимпульс', 'https://www.gidroimpulse.com/catalog/manufacture-of-rvd/', null, null, 'собственное оборудование для опрессовки', 'Заявляют изготовление РВД по чертежу, по каталожному номеру и по образцу — второй вариант важен: можно отдать оригинальный номер Caterpillar и получить рукав без разборки машины. Контакты на найденной странице не извлеклись, нужен отдельный заход на страницу контактов.', 'https://www.gidroimpulse.com/catalog/manufacture-of-rvd/', 'med', null),
  ('R1700G', 'ООО «Завод Таланмаш»', 'aftermarket', 'производитель-неоригинал', 'RU', 'Москва', 'изготовление манжет, уплотнений и ремкомплектов гидроцилиндров по чертежам заказчика', 'Таланмаш', 'https://talanmash.ru/', 'info@talanmash.ru', '+7 (495) 232-232-1', 'производство по чертежам и образцам, отправка по РФ', 'Прямо заявляют изготовление аналогов импортных манжет Busak+Shamban, Hallite, Parker, Simrit, Kastas, Merkel — это перечень производителей, чьи уплотнения стоят в гидроцилиндрах R1700G. Для ПДМ критично: ремкомплект цилиндра можно сделать в РФ за недели вместо ожидания оригинала.', 'https://talanmash.ru/products/izgotovlenie-po-vashim-chertezham/cuff_seals/filter/filter-remcomplect/', 'high', null),
  ('R1700G', 'КРПМС (Калугаремпутьмаш-Сервис)', 'aftermarket', 'производитель-неоригинал', 'RU', 'Калуга / Москва', 'производство уплотнений для гидроцилиндров (полиуретан, силикон, фторопласт, резина)', 'КРПМС, каталог Kastas', 'https://www.krpms.ru/catalog/uplotneniya/', 'msk@krpms.ru', null, 'производство и склад, поставка по РФ', 'Делают манжеты и уплотнения для гидроцилиндров производственного оборудования и строительной техники и отдельно ведут каталог уплотнений Kastas. Для R1700G — источник и штучного уплотнения по размеру, и полного ремкомплекта. Телефоны со страницы каталога вытянуть не удалось (страница с таблицами температур), звонить по общим контактам сайта.', 'https://www.krpms.ru/catalog/uplotneniya/', 'high', null),
  ('R1700G', 'ЗАО «Шахтинский завод Гидропривод»', 'aftermarket', 'производитель-неоригинал', 'RU', 'Шахты, Ростовская обл.', 'литейно-механический завод: зубья, коронки, траки, отливки из чугуна и стали, комплектующие горного оборудования', 'Гидропривод', 'https://gidroprivod.ru/', 'zavod@gidroprivod.ru', '+7 (863) 204-17-88', 'собственное литьё и мехобработка, продажа по ценам завода-изготовителя', 'Полный технологический набор под износ R1700G: отливки из чугуна и стали, зубья/коронки/траки, лазерная и плазменная резка, мехобработка, химико-термическая обработка, ремонт гидрооборудования. То есть коронку ковша и защиту можно заказать в РФ по образцу с термообработкой, а не только купить импортную.', 'https://gidroprivod.ru/catalog/komplektuyushchie-dlya-gorno-dobyvayushchego-oborudovaniya/zubya-koronki-traki/', 'high', null),
  ('R1700G', 'ГК «Профессионал» (Проф-ДСТ)', 'aftermarket', 'производитель-неоригинал', 'RU', 'Иваново', 'крупнейший российский производитель ковшей и навесного оборудования, освоено производство под Caterpillar', 'Профессионал', 'https://profdst.ru/', 'info@profdst.ru', '8 (800) 775-80-50', 'собственные производственные мощности, монтаж навесного, передвижная мастерская, ремонт ковшей', 'Новость на их сайте прямо об освоении производства быстросъёмных ковшей для техники Caterpillar — значит есть чертежи, оснастка и опыт по посадочным размерам Cat. Для R1700G перспективно по металлоконструкции: ковш 6 куб. м, защита днища, кромки, ремонт ковша с наплавкой. Это то звено, где импорт бессмыслен из-за веса и стоимости доставки.', 'https://profdst.ru/media/news/osvoeno-proizvodstvo-bystrosemnykh-kovshey-dlya-ekskavatornoy-tekhniki-firmy-caterpillar/', 'high', null),
  ('R1700G', 'Технопарк «Импульс»', 'aftermarket', 'производитель-неоригинал', 'RU', 'Москва', 'изготовление ковшей для любой спецтехники по чертежам оригинала', 'Импульс', 'https://www.impulse.su/', 'mail@impulse.su', '+7 (495) 926-35-41', 'производство по чертежам, доставка по РФ', 'Заявляют богатую базу чертежей оригинальных ковшей, включая ковши фронтальных погрузчиков — категория, к которой относится ковш ПДМ R1700G. Полезны как второй источник по металлоконструкции (торг с Профессионалом) и как исполнитель на нестандарт: усиленный ковш под конкретную породу.', 'https://www.impulse.su/stati/izgotovlenie-kovshey-dlya-lyuboy-spectekhniki/', 'med', null),
  ('R1700G', 'ООО «Армет» (Armet Group)', 'aftermarket', 'производитель-неоригинал', 'RU', null, 'российский бренд режущих элементов ковшей с производством в Китае', 'Armet', 'https://armetgroup.ru/get', 'info@armet.pro', '8 (800) 600-29-33', 'производства в Китае, поставка по РФ быстрее параллельного импорта (по их заявлению)', 'Полный ряд GET под системы крепления мировых брендов, включая Caterpillar: коронки, адаптеры, бокорезы, защиты ковша, зубья, стопоры/пальцы. Соответствие ISO 9001 и 16949, собственный запатентованный модификатор литья. ВАЖНО и честно: сами пишут «наши производства находятся в Китае» — это российское брендирование китайского литья, не российский завод. Для R1700G удобно тем, что счёт, НДС и гарантия российские.', 'https://armetgroup.ru/get', 'high', null),
  ('R1700G', 'ООО «УралГидроКомплект»', 'aftermarket', 'ремонт', 'RU', 'Челябинск', 'изготовление и ремонт гидроцилиндров, ремонт ковшей, есть раздел запчастей Caterpillar', 'УралГидроКомплект', 'https://ugk174.ru/', 'info@ugk174.ru', '+7 (912) 403-10-10', 'свой участок, доставка по РФ; сервисная почта serv@ugk174.ru', 'Для R1700G закрывает ремонтное звено, а не закупочное: изготовление гидроцилиндров, ремонт гидроцилиндров, восстановление наплавкой, расточка отверстий, ремонт ковшей и стрел, диагностика гидравлики. Отдельный раздел «Запчасти для CATERPILLAR». Это альтернатива покупке нового цилиндра целиком.', 'https://ugk174.ru/catalog/gidrotsilindry_caterpillar/', 'high', null),
  ('R1700G', 'ООО «Кентек»', 'aftermarket', 'торговец', 'RU', 'Санкт-Петербург', 'подбор и поставка аналогов фильтров и фильтроэлементов для техники Caterpillar', 'мультибренд (аналоги фильтров)', 'https://kentek.ru/applicability-filters/caterpillar/', 'info@kentek.ru', '8 (812) 326-07-12', 'поставка по РФ, подбор по модели техники', 'Не завод: сами формулируют как «подберём и поставим аналоги оригинальных фильтров и элементов». Ценность — готовая применимость по моделям Caterpillar на русском. В списке на странице перечислены погрузчики-экскаваторы и мини-экскаваторы; подземных ПДМ серии R в явном виде нет, значит по R1700G подбор пойдёт от номера Cat, а не от модели.', 'https://kentek.ru/applicability-filters/caterpillar/', 'high', null),
  ('R1700G', 'ООО «Невский фильтр»', 'aftermarket', 'производитель-неоригинал', 'RU', 'Санкт-Петербург', 'российский завод фильтров и фильтроэлементов', 'Невский фильтр', 'https://nevsky-filter.ru/', 'info@nevsky-filter.ru', null, 'производство СПб, 2000+ SKU, поставка по РФ', 'Топливные, масляные, воздушные и салонные фильтры, отдельно заявлена спецтехника. Применимость именно к набору R1700G (423-8524, 1R-0762, 1R-1808, 1R-0722, 6I-2510, 132-7167, 231-0167) на сайте не подтверждена — нужен запрос на подбор или контрактное изготовление по образцу. Потенциально самое дешёвое решение по ТО-расходникам.', 'https://nevsky-filter.ru/', 'med', null),
  ('R1700G', 'ООО «Экофил» (EKOFIL)', 'aftermarket', 'производитель-неоригинал', 'RU', null, 'производство автомобильных фильтров и фильтроэлементов с 1996, включая спецтехнику', 'EKOFIL', null, null, null, 'производство РФ, продажи через дистрибьюторов автокомпонентов', 'Воздушные, масляные, топливные фильтры, топливные сепараторы для автомобилей, сельхоз- и спецтехники. Сепараторы важны: на R1700G стоит 423-8524 (топливный грубой очистки с водоотделением). Прямых кросс-номеров на Caterpillar не видел — проверять через их техподдержку по образцу. Собственный сайт завода в выдаче не нашёлся, данные — из карточки поставщика в отраслевом каталоге; юрлицо и адрес производства нужно подтвердить.', 'https://www.rti-expert.ru/suppliers/ooo_ekofil/', 'low', null),
  ('R1700G', 'СОАО «ДИФА» (DIFA)', 'aftermarket', 'производитель-неоригинал', 'BY', 'Витебск', 'белорусский завод фильтров полного цикла (проектирование — производство — поставка)', 'DIFA', 'https://difa.by/', null, null, 'завод Витебск; в РФ официальный поставщик «ДИФА-АВК» (difa-avk.ru)', '1000+ типов фильтров и фильтроэлементов по воздуху, топливу, маслу и рабочей жидкости гидросистем; в каталоге есть позиции с указанием аналога Caterpillar. Для R1700G это доступный в ЕАЭС канал без ВЭД: расчёт в рублях, доставка за дни. Конкретное соответствие нашему набору фильтров нужно проверить по их подборщику.', 'https://difa.by/', 'med', null),
  ('R1700G', 'ООО «Реготмас»', 'aftermarket', 'производитель-неоригинал', 'RU', null, 'производство фильтроэлементов для очистки масла и рабочей жидкости гидросистем', 'Реготмас', 'https://regotmas.ru/products-regotmas/', null, null, 'производство РФ; марка широко копируется («аналоги Реготмас»)', 'Сетчатые всасывающие фильтры с втрое большей площадью фильтрации по их заявлению — пригодны как аналог всасывающих сеток гидробака. Привязки к Caterpillar нет вообще, подбор только по посадочным и тонкости фильтрации. На сайте указана только почта на mail.ru, что для промышленного поставщика настораживает — проверять юрлицо.', 'https://regotmas.ru/products-regotmas/', 'low', null),
  ('R1700G', 'ООО «Традиция-К»', 'aftermarket', 'торговец', 'RU', 'Москва', 'поставщик зубьев и коронок под системы Caterpillar, в т.ч. неоригинальный бренд Nova', 'Nova, Caterpillar', 'https://www.tradicia-k.ru/catalog/zubya-cat/', 'company@tradicia-k.ru', '+7 (495) 727-00-69', 'склад в Москве, розничные цены в рублях на сайте', 'Не завод, а торговая площадка с наличием: в каталоге зубья Caterpillar по номерам (6Y-6335 Nova, серии 1U-18xx, 8E-16xx и др.) с ценами и запросом. Полезен для быстрой замены расходника на R1700G и как рублёвый ориентир цены против китайского прямого импорта.', 'https://www.tradicia-k.ru/catalog/zubya-cat/', 'high', null),
  ('R1700G', 'ООО «Аймашинери» (imachinery.ru)', 'aftermarket', 'торговец', 'RU', 'Москва', 'официальный дистрибьютор Costex Tractor Parts (CTP) в России', 'CTP, Caterpillar', 'https://imachinery.ru/brendy/costex/', 'zakaz@imachinery.ru', '+7 (495) 983-00-71', 'поставка по РФ, часть номенклатуры со склада', 'Рабочий канал получить неоригинал CTP в РФ по рублёвому договору вместо прямого импорта из Майами: комплекты ДВС, фрикционные диски, уплотнения, GET. Для R1700G это способ закрыть позиции, по которым оригинал Cat в РФ недоступен или ждать месяцами.', 'https://imachinery.ru/brendy/costex/', 'high', null),
  ('R1700G', 'ООО «ЗИПТЕХ-СЕРВИС»', 'aftermarket', 'торговец', 'RU', 'Москва', 'официальный дистрибьютор бренда CTP в России', 'CTP', 'https://www.zipteh.ru/o-nas/oficialnyj-distribyutor-ctp/', 'zakaz@zipteh.ru', '8 (800) 200-99-38', 'поставка по РФ', 'Второй независимый дистрибьютор CTP — нужен для торга: одна и та же номенклатура CTP у двух дистрибьюторов даёт вилку цен. При закупке по R1700G запрашивать одинаковый список номеров у обоих плюс у 74parts.', 'https://www.zipteh.ru/o-nas/oficialnyj-distribyutor-ctp/', 'high', null),
  ('R1700G', 'МС Партс (74parts.ru)', 'aftermarket', 'торговец', 'RU', 'Челябинск', 'поставка запчастей CTP Costex со склада в России, фрикционные диски Caterpillar', 'CTP, Costex, Caterpillar', 'https://74parts.ru/info/brands/ctp_costex/', 'zakaz@74parts.ru', '+7 (351) 223-34-41', 'склад в России заявлен прямо', 'Третий канал CTP и при этом с собственным каталогом по трансмиссии Caterpillar (в каталоге, например, фрикционный диск 6Y-7929 для 428/430 с рублёвой ценой). Для R1700G полезен как источник рублёвых цен на диски ПКП и сравнения с китайской ценой Fricwel/Henli.', 'https://74parts.ru/info/brands/ctp_costex/', 'high', null),
  ('R1700G', 'MineCon (ТОО, minecon.kz)', 'aftermarket', 'торговец', 'KZ', 'Алматы', 'сертифицированный официальный дистрибьютор Costex Tractor Parts (CTP) в Казахстане', 'CTP, Caterpillar', 'https://minecon.kz/', null, '+7 (700) 727-38-88', 'склады Алматы и США; отгрузка по Казахстану, РФ, СНГ и Центральной Азии', 'Для горной техники в СНГ это удобный обход: CTP приходит через Казахстан внутри ЕАЭС. Заявляют запчасти, оборудование и двигатели для Caterpillar. Публичная почта на сайте — персональная, поэтому не приведена; выходить через сайт или телефон.', 'https://minecon.kz/', 'med', null),
  ('R1700G', 'ООО «Восточная Техника» (Vostochnaya Technica)', 'traders', 'дилер', 'RU', 'Новосибирск', 'официальный дилер Caterpillar и SEM по Сибири, Якутии и северу Дальнего Востока', 'Caterpillar, SEM', 'https://www.vost-tech.ru/', 'info@vost-tech.ru', '8-800-250-7060', 'региональные склады запчастей и мобильные сервисные бригады в Новосибирске, Красноярске, Иркутске, Чите, Норильске, Магадане, Якутске, Мирном, Удачном, Нерюнгри, Алдане, Новокузнецке, Белово, Братске', 'Главный канал ОРИГИНАЛА Cat именно там, где стоят рудники с R1700G (Норильск, Якутия, Кузбасс, Забайкалье). Своя служба ремонта двигателей Cat (C11/C15) с диагностикой и стендом. В таможне 2023 проходит как импортёр частей Cat напрямую от Caterpillar Inc. (DE, US) — то есть канал ввоза оригинала работает. Юридически 100 % дочка британской Vostochnaya Technica UK Ltd, поэтому поставки продолжаются после ухода Caterpillar; это же значит санкционный риск для контрагента — проверять на момент сделки.', 'https://www.vost-tech.ru/kontakty/', 'high', null),
  ('R1700G', 'ООО «Цеппелин Русланд» (Zeppelin Russland)', 'traders', 'дилер', 'RU', 'Красногорск (Московская обл.)', 'официальный дилер Caterpillar по Центральному, Северо-Западному, Приволжскому и Южному ФО, включая подземную горную технику', 'Caterpillar', 'https://www.zeppelin.ru/', null, '+7 495 130-35-35', 'склад оригинальных запчастей + Центр восстановления компонентов (сертифицированный ребилд узлов)', 'Держит карточку именно R1700G и R1700 в каталоге (модель помечена архивной, но страница по ней живая) — значит машина продавалась через них и по ней есть SEBP/сервисная история. Поставляли ПДМ Cat R2900G на рудник АО «Апатит» в Кировске, то есть по LHD опыт подтверждён. Их «Восстановление техники и компонентов» — наш прямой альтернативный путь вместо покупки нового узла.', 'https://zeppelin.ru/products/mashiny-podzem/r1700g', 'high', null),
  ('R1700G', 'Borusan Cat Kazakhstan (ИП «Борусан Макина Казахстан»)', 'traders', 'дилер', 'KZ', 'Алматы', 'официальный дилер Caterpillar в Казахстане, в т.ч. по подземной горной технике', 'Caterpillar, SEM', 'https://www.borusancat.kz/', null, '+7 727 244 33 77', 'постоянный склад запчастей в Казахстане; заказ онлайн через Parts.cat.com 24/7', 'У них в каталоге новой техники есть отдельная страница R1700G с описанием изнашиваемых элементов (MAS — механически крепящиеся накладки, MAWPS — броневые плиты ковша). Это лучший доступный источник официальной применимости по R1700G на русском языке в СНГ и рабочий канал закупки оригинала в обход российских ограничений (ЕАЭС, без таможни внутри союза).', 'https://www.borusancat.kz/en/equipment/new/13866077/Underground-Hard-Rock/18233686/R1700G', 'high', null),
  ('R1700G', 'Borusan Cat Kazakhstan — Центр восстановления компонентов', 'traders', 'ремонт', 'KZ', 'Алматы', 'сертифицированный ребилд коробок передач и гидротрансформаторов Caterpillar по стандартам завода', 'Caterpillar', 'https://www.borusancat.kz/ru/restoration-repair/remont-korobok-peredach-i-gidrotransformatorov', null, '+7 727 244 33 77', 'цех восстановления, стендовые испытания по спецификации завода', 'Прямая замена покупке КП/гидротрансформатора на R1700G: заявлено восстановление всех коробок и гидротрансформаторов Cat — от 416 до 797, то есть модельный ряд ПДМ попадает. Цикл: мойка, разборка, инспекция деталей, отчёт по каждому компоненту, сборка, тест по спецификации. Для нас это ориентир по цене «ремонт vs новый узел» и площадка в ЕАЭС.', 'https://www.borusancat.kz/ru/restoration-repair/remont-korobok-peredach-i-gidrotransformatorov', 'high', null),
  ('R1700G', 'Borusan Cat Kyrgyzstan (Borusan Makina)', 'traders', 'дилер', 'KG', 'Бишкек', 'официальный дилер Caterpillar в Кыргызстане', 'Caterpillar', null, null, null, 'поставка через структуру Borusan Holding (Турция)', 'Второй вход в ту же дилерскую сеть Borusan, но с киргизской юрисдикцией — полезен как альтернативный маршрут платежа и ввоза внутри ЕАЭС, когда казахстанский контур упирается в комплаенс. Заявлены оригинальные масла и запчасти Cat для горной техники.', 'https://www.amcham.kg/en/members/borusan-makina/', 'med', null),
  ('R1700G', 'Barloworld Mongolia LLC', 'traders', 'дилер', 'MN', 'Улан-Батор', 'официальный дилер Caterpillar в Монголии (горная добыча, дороги, энергетика)', 'Caterpillar', null, null, null, 'дилерский склад в Монголии', 'Монголия — ближайший к нашим сибирским рудникам рынок подземных Cat с живой дилерской поддержкой и без российских ограничений. Годится как источник SEBP/номеров и как канал разовой закупки редкой позиции по R1700G, если РФ-канал закрыт.', 'https://catused.cat.com/en/dealer.aspx?orgid=%7B42e2f3fa-97f8-46f0-916c-673c0c9b2063%7D', 'med', null),
  ('R1700G', 'Wagner Asia Equipment LLC', 'traders', 'дилер', 'MN', 'Улан-Батор', 'дилер Caterpillar в Монголии, крупнейший поставщик тяжёлой техники в стране', 'Caterpillar', null, null, null, 'собственный склад и сервис в Монголии', 'Второй монгольский дилер Cat. Полезен тем же, чем Barloworld: подземные Cat в Монголии эксплуатируются массово, значит на складе реально лежат расходники и износ по линейке R1300–R2900, родственной нашей R1700G.', 'http://www.mongolianbusinessdatabase.com/base/companydetials?id=3449', 'low', null),
  ('R1700G', 'ООО «БИЗНЕС СЕРВИС»', 'traders', 'торговец', 'RU', 'Новокузнецк (Кемеровская обл.)', 'поставщик запасных частей для горно-шахтного и карьерного оборудования', 'Caterpillar и др. горная техника', 'https://bs-nk.ru/', 'ooo.biznesservis@bk.ru', '+7 912 600 82 73', 'поставка по всей России, входной контроль перед отправкой', 'Самый частый импортёр в нашей выборке таможни по подземной технике — 18 строк из 109 (seed_customs_lhd.json), больше, чем у кого-либо. ИНН 4217173655, Новокузнецк, ул. Вокзальная 22 — то есть сидит в Кузбассе, рядом с рудниками. Первый, кому имеет смысл отдать наш перечень по R1700G: он уже физически возил это.', 'https://bs-nk.ru/kontakty', 'high', null),
